"""Generate the dependency-free GitHub Pages website. Run: python3 build.py."""
from pathlib import Path
import json,html,re,math
ROOT=Path(__file__).parent; OUT=ROOT.parent; D=json.loads((ROOT/'data/content.json').read_text()); PROFILE=json.loads((ROOT/'data/profile.json').read_text())
def esc(s): return html.escape(str(s),quote=True)
SCHOLAR='https://scholar.google.com/citations?user=4OMm56YAAAAJ&hl=en'
EMAIL='aniruddha_bora@txstate.edu'
NAV=[('Research','/portfolio/'),('Publications','/publications/'),('SPARKS Lab','/spark/'),('Teaching','/teaching/'),('CV','/cv/')]
def link(url,label,cls=''): return f'<a class="{cls}" href="{esc(url)}">{label}</a>'
def button(url,label,primary=False): return link(url,label+' <span aria-hidden="true">↗</span>','button'+(' primary' if primary else ''))
def eyebrow(s):return f'<div class="eyebrow">{s}</div>'
def top(kicker,title,subtitle=''):return f'<div class="page-intro">{eyebrow(kicker)}<h1>{title}</h1><p>{subtitle}</p></div>'
def sectionhead(kicker,title,url='',label='Explore more'):return f'<div class="section-top"><div>{eyebrow(kicker)}<h2>{title}</h2></div>{link(url,label+" ↗","text-link") if url else ""}</div>'
def contact():return f'''<section class="contact" id="contact"><div>{eyebrow('Connect')}<h2>Good science starts<br>with a conversation.</h2><p>Interested in research collaboration or joining SPARKS Lab? I welcome conversations across computer science, mathematics, physics, and engineering.</p></div><div class="contact-details"><a class="email" href="mailto:{EMAIL}">{EMAIL} ↗</a><p style="margin-top:20px">Department of Computer Science · Texas State University<br>310D Comal · San Marcos, Texas 78666</p><div class="social"><a href="{SCHOLAR}">Google Scholar ↗</a><a href="https://github.com/aniruddhabora">GitHub ↗</a><a href="https://orcid.org/0000-0001-8015-9924">ORCID ↗</a><a href="https://www.linkedin.com/in/aniruddha-bora-49b73a80/">LinkedIn ↗</a></div></div></section>'''
def page(path,title,body,desc='Research in scientific machine learning, neural operators, and physics-informed AI. Aniruddha Bora, Assistant Professor at Texas State University.'):
 nav=''.join(f'<a href="{u}"'+(' aria-current="page"' if path==u else '')+f'>{n}</a>' for n,u in NAV)
 out=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{esc(title)} | Aniruddha Bora</title><meta name="description" content="{esc(desc)}"><meta name="theme-color" content="#0b1015"><meta property="og:title" content="{esc(title)} | Aniruddha Bora"><meta property="og:description" content="{esc(desc)}"><meta property="og:type" content="website"><link rel="icon" href="/assets/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="/assets/style.css"><script defer src="/assets/main.js"></script><script defer src="/assets/scientific-field.js"></script></head><body><a class="skip" href="#main">Skip to content</a><header><div class="wrap"><a class="brand" href="/" aria-label="Aniruddha Bora home"><span class="mark" aria-hidden="true"><span>AB</span></span><span>Aniruddha Bora<small>SCIENTIFIC AI · TEXAS STATE</small></span></a><button class="menu" aria-expanded="false" aria-controls="navigation">Menu</button><nav id="navigation" aria-label="Main navigation">{nav}<a class="nav-contact" href="#contact">Let's connect ↗</a></nav></div></header><main id="main" class="wrap">{body}{contact()}</main><footer><div class="wrap"><span>© 2026 Aniruddha Bora</span><span><a href="/awards/">Awards</a> &nbsp; / &nbsp; <a href="/grants/">Funding</a> &nbsp; / &nbsp; <a href="/talks/">Talks</a> &nbsp; / &nbsp; <a href="/innovation/">Innovation</a> &nbsp; / &nbsp; <a href="/service/">Service</a></span></div></footer></body></html>'''
 dest=OUT/path.strip('/')/'index.html' if path!='/' else OUT/'index.html';dest.parent.mkdir(parents=True,exist_ok=True);dest.write_text(out)
P=sorted(D['publications'],key=lambda p:p.get('date',''),reverse=True)
TYPES={'manuscripts':'Journal article','submitted':'Submitted / draft','conferences':'Conference / workshop','books':'Book chapter','software':'Software'}
def pub(p,filterable=False):
 attrs=f' data-publication data-category="{p["category"]}"' if filterable else ''
 title=link(p['paperurl'],esc(p['title'])) if p.get('paperurl') else esc(p['title'])
 arrow=f'<a class="arrow" href="{esc(p["paperurl"])}" aria-label="{esc(p.get("link_label","Read")+": "+p["title"])}">↗</a>' if p.get('paperurl') else '<span></span>'
 authors=f'<div class="authors">{esc(p["authors"])}</div>' if p.get('authors') else ''
 status=f'<div class="pub-status">{esc(p["status"])}</div>' if p.get('status') else ''
 return f'<article class="pub"{attrs}><span class="year">{esc(p.get("display_year",p["date"][:4]))}</span><div><h3>{title}</h3>{authors}<div class="venue">{esc(p["venue"])} &nbsp; <span class="type">{TYPES[p["category"]]}</span></div>{status}</div>{arrow}</article>'
def timeline(items):
 return '<div class="timeline">'+''.join(f'<article><div class="date">{esc(date)}</div><div><h3>{esc(title)}</h3><p>{esc(description)}</p></div></article>' for date,title,description in items)+'</div>'
def profile_section(key,title):
 return f'<section class="block"><h2 style="margin-bottom:28px">{title}</h2>{timeline(PROFILE[key])}</section>'
def field_fallback():
 lines=[]
 for j in range(29):
  pts=[]
  for i in range(100):
   x=-2.6+5.2*i/99; z=-2.5+j*5/28
   y=math.exp(-.23*(x*x+z*z))*math.sin(x*1.9+z*1.3)*1.25
   sx=280+x*73+z*30;sy=250+z*31-y*75-x*5
   pts.append(f'{sx:.1f},{sy:.1f}')
  lines.append(f'<polyline points="{" ".join(pts)}" fill="none" stroke="url(#fieldcolor)" stroke-width="1" opacity="{.35+j/50:.2f}"/>')
 for i in range(0,100,4):
  pts=[]
  for j in range(29):
   x=-2.6+5.2*i/99;z=-2.5+j*5/28;y=math.exp(-.23*(x*x+z*z))*math.sin(x*1.9+z*1.3)*1.25
   pts.append(f'{280+x*73+z*30:.1f},{250+z*31-y*75-x*5:.1f}')
  lines.append(f'<polyline points="{" ".join(pts)}" fill="none" stroke="#82e3d7" stroke-width=".6" opacity=".23"/>')
 return f'''<div class="field"><div class="field-label"><span class="dot"></span>PHYSICS × LEARNING × DISCOVERY</div><svg viewBox="0 0 560 470" role="img" aria-label="Abstract scientific field visualized as a curved wireframe mesh"><defs><linearGradient id="fieldcolor"><stop stop-color="#4e9eab"/><stop offset=".55" stop-color="#8df1dc"/><stop offset="1" stop-color="#eeb57e"/></linearGradient><radialGradient id="glow"><stop stop-color="#44887b" stop-opacity=".2"/><stop offset="1" stop-color="#0b1015" stop-opacity="0"/></radialGradient></defs><ellipse cx="285" cy="255" rx="270" ry="185" fill="url(#glow)"/><g stroke="#293941" stroke-width=".7"><path d="M30 360L290 415L540 325M290 415V100" fill="none"/><path d="M60 112h22m-11-11v22M484 144h22m-11-11v22M430 386h22m-11-11v22"/></g><g class="wave">{''.join(lines)}</g><g fill="#8da1ab" font-family="monospace" font-size="10"><text x="297" y="109">u(x,t)</text><text x="526" y="345">x</text><text x="25" y="382">t</text></g></svg><div class="field-label bottom">A CONCEPTUAL SCIENTIFIC FIELD</div><button class="pause" aria-pressed="false">Pause motion</button></div>'''
def field():
 fallback=field_fallback()
 fallback=re.sub(r'<button class="pause".*?</button>','',fallback)
 fallback=fallback.replace('class="field"','class="field-fallback"',1)
 return f'''<div class="field field-lab" data-scientific-field><div class="field-kicker"><span class="field-status-dot"></span>AN EXPLORATION OF SCIENTIFIC SYSTEMS</div><div class="field-stage">{fallback}<canvas aria-label="Interactive conceptual scientific visualization. Choose vortex, waves, or attractor using the buttons below." role="img"></canvas></div><div class="field-controls" hidden><div class="field-modes" role="group" aria-label="Choose a scientific visualization"><button data-field-mode="vortex" aria-pressed="true">01 <span>Vortex</span></button><button data-field-mode="waves" aria-pressed="false">02 <span>Waves</span></button><button data-field-mode="attractor" aria-pressed="false">03 <span>Attractor</span></button></div><div class="field-caption" data-field-caption aria-live="polite">VORTEX · FLOW THROUGH A THREE-DIMENSIONAL FIELD</div><div class="field-tools"><span data-field-hint>MOVE TO EXPLORE · TAP TO SEND A PULSE</span><div><button data-field-pulse aria-label="Send a pulse through the scientific visualization">Pulse ↗</button><button data-field-pause aria-pressed="false">Pause motion</button></div></div></div><div class="field-disclaimer">CONCEPTUAL VISUALIZATION · NOT RESEARCH DATA</div></div>'''
AREAS=[('01','Physics-informed learning','Learning methods that respect physical laws, combining differential equations and data to model complex systems.',['PINNs','Neural operators','Multiphysics']),('02','Generative AI for science','Generative models that recover fine-scale structure and improve scientific prediction, from turbulent flows to climate.',['Diffusion models','Earth systems','Turbulence']),('03','Scientific discovery & decision-making','Interpretable, data-efficient AI and autonomous decision-making through reinforcement learning, agentic systems, and physical knowledge.',['Reinforcement learning','Agentic AI','Symbolic discovery'])]
def areas():return '<div class="research-grid">'+''.join(f'<article class="research-card"><span class="number">{i} / RESEARCH DIRECTION</span><h3>{t}</h3><p>{d}</p><div class="tags">'+''.join(f'<span>{x}</span>' for x in tags)+'</div></article>' for i,t,d,tags in AREAS)+'</div>'
PROJECTS=[('port_3.md','neural-operators-diffusion','Generative AI · Fluid dynamics','Resolving the missing scales of turbulence','Combining neural operators and diffusion models to recover high-frequency flow structures.','NO_DM.webp','NO_DM.md'),('port_4.md','earth-system-modeling','Neural operators · Climate','Bringing learned corrections into Earth systems','Online neural operator updates for stable, multiyear hybrid climate simulations.','main_fig.webp','MM.md'),('portfolio-1.md','inverse-design','Inverse design · Materials','Designing materials from desired behavior','Data-efficient neural operators for the characterization and inverse design of stochastic metamaterials.','Meta.webp','ADM.md'),('port_2.md','ultrafast-heat-transfer','Physics-informed AI · Thermal transport','Learning heat transfer at ultrafast scales','Neural network modeling of electron and lattice dynamics in laser-heated thin films.','PTTM.webp','PTTM_2021.md')]
def sparks_identity(prefix='lab',compact=False):
 svg=(OUT/'images/sparks-logo-enhanced.svg').read_text()
 # Scope SVG paint-server IDs so multiple instances can safely share a page.
 svg=re.sub(r'id="([^"]+)"',lambda m:'id="'+prefix+'-'+m.group(1)+'"',svg)
 svg=re.sub(r'url\(#([^)]+)\)',lambda m:'url(#'+prefix+'-'+m.group(1)+')',svg)
 return '<div class="sparks-identity'+(' compact' if compact else '')+'" data-sparks><div class="sparks-art" role="img" aria-label="SPARKS Lab logo: an amber and cyan infinity network unites AI and science above the SPARKS wordmark">'+svg+'</div><div class="sparks-animation-controls"><span>AI × SCIENCE</span><button type="button" class="sparks-replay" aria-label="Replay SPARKS Lab logo animation" hidden>Replay animation ↻</button></div></div>'

def project_cards(selected=PROJECTS):return '<div class="work-grid">'+''.join(f'<a class="work" href="/research/{slug}/"><div class="work-image"><img src="/images/{im}" alt="Research figure: {esc(title)}" loading="lazy" width="660" height="360"></div><div class="meta">{tag}</div><h3>{title}</h3><p>{desc}</p><span class="text-link">Explore the research ↗</span></a>' for _,slug,tag,title,desc,im,_ in selected)+'</div>'
body=f'''<section class="hero"><div>{eyebrow('Assistant Professor · Computer Science')}<h1>Aniruddha<br><span>Bora.</span></h1><div class="tagline">AI for a world<br>governed by physics.</div><p>I connect machine learning, applied mathematics, and scientific computing to understand and model complex physical systems.</p><div class="actions">{button('/portfolio/','Explore my research',True)}{button('/publications/','Publications')}</div></div>{field()}</section><div class="affiliation"><div><strong>Texas State University</strong><span>Department of Computer Science</span></div><div><strong>Principal Investigator · SPARKS Lab</strong><span>Scientific AI, grounded in domain knowledge</span></div><div class="location">SAN MARCOS, TEXAS<br>29.8833° N / 97.9414° W</div></div><section class="block">{sectionhead('Research philosophy','Physical insight. Computational intelligence.')}{areas()}</section><section class="block">{sectionhead('Selected research','From equations to discovery.','/portfolio/','All research')}{project_cards(PROJECTS[:2])}</section><section class="block">{sectionhead('Recent scholarship','Ideas in print.','/publications/','All publications')}{''.join(pub(p) for p in [x for x in P if x['category']=='manuscripts'][:4])}</section><section class="block about-grid"><div><img class="portrait" src="/images/profile_2.webp" alt="Aniruddha Bora in front of bookshelves" loading="lazy" width="670" height="758"></div><div class="about-copy">{eyebrow('About me')}<h2>Working at the intersection<br>of disciplines.</h2><p>I am an Assistant Professor of Computer Science at Texas State University, where I lead SPARKS Lab. My work brings together ideas from computer science, applied mathematics, and scientific computing.</p><p>Before joining Texas State, I was a Postdoctoral Research Associate at Brown University. I earned my Ph.D. in Computational Analysis and Modeling from Louisiana Tech University in 2021. In Summer 2026, I was a J. Tinsley Oden Faculty Fellow at UT Austin.</p><p>My focus is on robust, interpretable learning algorithms that combine physical insight with modern AI.</p><div class="actions">{button('/cv/','View academic CV')}{link(SCHOLAR,'Google Scholar ↗','text-link')}</div></div></section><section class="block"><div class="lab-banner"><div>{eyebrow('The research group')}{sparks_identity("home",True)}</div><div><h3>Curiosity across boundaries.</h3><p class="sparks-expansion"><strong>S</strong>cientific <strong>P</strong>rediction through <strong>A</strong>I <strong>R</strong>esearch, <strong>K</strong>nowledge &amp; <strong>S</strong>imulation</p><p>We bring together researchers from computing, mathematics, physics, and engineering to build learning methods for scientific systems.</p>{button('/spark/','Meet the lab',True)}</div></div></section>'''
