page('/portfolio/','Research',top('Research portfolio','Learning the language of physical systems.','Scientific machine learning for fluid dynamics, climate, thermal transport, and materials design.')+f'<section class="block" style="padding-top:15px">{project_cards()}</section><section class="block">{sectionhead("Research directions","Methods that connect across domains.")}{areas()}</section>')
for filename,slug,tag,title,desc,im,paperfile in PROJECTS:
 proj=next(x for x in D['portfolio'] if x['source_file']==filename);paper=next(x for x in P if x['source_file']==paperfile)
