 extra='<div class="work-grid"><figure><img src="/images/E1.gif" alt="Electron temperature evolution"><figcaption>Electron temperature evolution</figcaption></figure><figure><img src="/images/L1.gif" alt="Lattice temperature evolution"><figcaption>Lattice temperature evolution</figcaption></figure></div>' if filename=='port_2.md' else ''
